/** 把墨色占位替换成实际颜色，拼成完整 SVG。 */
export function heroPatternSvg(pattern: HeroPattern, ink: string, inkOpacity: number): string {
  const body = pattern.body.replace('fill="#000"', `fill="${ink}" fill-opacity="${inkOpacity}"`)
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${pattern.width}" height="${pattern.height}" viewBox="0 0 ${pattern.width} ${pattern.height}">${body}</svg>`
}

/** 转义规则与 heropatterns.com 一致：" → ' ，再编码 & # < > 。 */
export function heroPatternDataUri(
  pattern: HeroPattern,
  ink: string,
  inkOpacity: number,
): string {
  const svg = heroPatternSvg(pattern, ink, inkOpacity)
  return (
    'data:image/svg+xml,' +
    svg
      .replace(/"/g, "'")
      .replace(/&/g, '%26')
      .replace(/#/g, '%23')
      .replace(/</g, '%3C')
      .replace(/>/g, '%3E')
  )
}
